@startuml

class SensorController {
  + systemName : string
  + querySensorValues(sensorId : int) : float
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalPowerConsumption : float
}

class SensorValue {
  + value : float
  + timestamp : datetime
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + checkThresholds() : boolean
  + sendAlert() : void
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Inhabitant "*" -- "1" Apartment
Inhabitant "0..1 admin" -- "1" SensorController
Room "1" *-- "1..*" Sensor
Sensor "1" *-- "1..*" SensorValue
Sensor "1" -- "0..1" SensorValue : lastValue
SensorController "1" -- "1" EMonitor : attachedTo
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

